  ('Nutrammon® 34.5-0-0', 'DEKAGRO', 'granular', '34.5', '17.25', '17.25', null, '0', '0', null, null, null, null, 'true', 'Analysis from the product name; add the brand and the nitrogen forms'),
  ('Nitrocan® 26 26-0-0', 'DEKAGRO', 'granular', '26', '13', '13', null, '0', '0', null, '11', null, null, 'true', 'Analysis from the product name; add the brand the nitrogen forms and CaO if printed on the bag'),
  ('Fertammon® 26-0-0 (+29 SO3)', 'DEKAGRO', 'granular', '26', '18.7', '7.3', null, '0', '0', '29', null, null, null, 'true', 'Analysis from the product name; add the brand and the nitrogen forms'),
  ('Sulfogran® 21-0-0 (+60 SO3)', 'DEKAGRO', 'granular', '21', null, null, null, '0', '0', '60', null, null, null, 'true', 'Analysis from the product name; add the brand and the nitrogen forms')
on conflict (name) do update set
  brand = excluded.brand,
  form = excluded.form,
  n_pct = excluded.n_pct,
  n_nh4_pct = excluded.n_nh4_pct,
  n_no3_pct = excluded.n_no3_pct,
  n_urea_pct = excluded.n_urea_pct,
  p2o5_pct = excluded.p2o5_pct,
  k2o_pct = excluded.k2o_pct,
  so3_pct = excluded.so3_pct,
  cao_pct = excluded.cao_pct,
  mgo_pct = excluded.mgo_pct,
  micro = excluded.micro,
  active = excluded.active,
  source = excluded.source;

-- Fertilisers saved in seasons before the nitrogen forms were known: copy the forms from
-- the product, only where the saved total N is still the product's and no form is saved yet.
update public.fertilizer_applications a set
  n_nh4_pct  = p.n_nh4_pct,
  n_no3_pct  = p.n_no3_pct,
  n_urea_pct = p.n_urea_pct
from public.fertilizer_products p
where a.product_id = p.id
  and a.n_nh4_pct is null and a.n_no3_pct is null and a.n_urea_pct is null
  and a.n_pct is not distinct from p.n_pct
  and (p.n_nh4_pct is not null or p.n_no3_pct is not null or p.n_urea_pct is not null);

commit;

